from pathlib import Path
import shutil,hashlib,json
lab=Path('F:/Projects/tyrax2-lab-20261001');base=lab/'arena-check-night';dst=lab/'borrow-trial'
assert not dst.exists()
ignore=shutil.ignore_patterns('obj','*.log','*.elf','*.elf.sym','*.p2s','ps2link.run')
shutil.copytree(base/'tyra',dst/'tyra',ignore=ignore)
shutil.copytree(base/'game',dst/'game',ignore=ignore)
rel=Path('engine/inc/renderer/core/paths/path1/frame_chain_arena.hpp')
old=(base/'tyra'/rel).read_text(encoding='utf-8')
new=(lab/'immutable-borrow-candidate/frame_chain_arena.hpp').read_text(encoding='utf-8')
def body(s):
 a=s.index('  bool borrow(');b=s.index('  void retire(',a)
 return s[a:b]
oldbody=body(old);newbody=body(new)
assert oldbody!=newbody
assert old.replace(oldbody,newbody)==new
candidatebody=newbody[newbody.index('{')+1:newbody.rfind('}')]
baselinebody=oldbody[oldbody.index('{')+1:oldbody.rfind('}')]
trialbody='  bool borrow(uint32_t address, uint32_t qwords, uint32_t bankMask) {\n    if (!BorrowExperiment::enabled) {'+baselinebody+'    }'+candidatebody+'  }\n'
trial=old.replace(oldbody,trialbody)
trial=trial.replace('namespace Tyra {','namespace Tyra {\nnamespace BorrowExperiment { inline bool enabled = false; }',1)
(dst/'tyra'/rel).write_bytes(trial.encode())
p=dst/'game/src/terrain_game.cpp';s=p.read_text(encoding='utf-8')
s='#include "renderer/core/paths/path1/frame_chain_arena.hpp"\n'+s
needle='void TerrainGame::loop() {';assert s.count(needle)==1
s=s.replace(needle,r'''void TerrainGame::loop() {
  static unsigned phase=0;
  static bool announced=false,done=false;
  if(!announced){printf("LOG: BORROWTRIAL phase=0 first=%lu enabled=0\n",(unsigned long)ftrig::frame);fflush(stdout);announced=true;}
  const unsigned desired=ftrig::frame/2200;
  if(desired<=2 && desired!=phase){
    engine->renderer.core.synchronizeFrame(); phase=desired;
    Tyra::BorrowExperiment::enabled=phase==1;
    printf("LOG: BORROWTRIAL phase=%u first=%lu enabled=%u\n",phase,(unsigned long)ftrig::frame,(unsigned)Tyra::BorrowExperiment::enabled);fflush(stdout);
    loadScene(currentScene);
  }
  if(desired>2 && !done){
    printf("LOG: BORROWTRIAL done first=%lu\n",(unsigned long)ftrig::frame);fflush(stdout);done=true;
  }
''')
p.write_bytes(s.encode())
files=[dst/'tyra'/rel,p]
meta={'phases':['baseline before','one-search borrowing','baseline restored'],'frames_per_phase':2200,'warm_work_start_offset':1100,'work_sample_count':512,'source_game':str(base/'game'),'source_engine':str(base/'tyra'),'candidate_header_sha256':hashlib.sha256((lab/'immutable-borrow-candidate/frame_chain_arena.hpp').read_bytes()).hexdigest(),'note':'Same ELF runtime branch in both arms; no new probes/waits/hold. Scene synchronized and reloaded between phases. Diagnostic A/B, not production acceptance.','artifacts':{str(p.relative_to(dst)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files}}
